module.exports = function (RED) {
    function WaitNode(config) {
        RED.nodes.createNode(this, config);
        const node = this;

        node.waitType = config.waitType;
        node.event_type = config.event_type;
        node.location = config.location;
        node.duration = parseFloat(config.duration);
        node.unit = config.unit;

        node.on('input', function (msg, send, done) {
            if (node.waitType === "time_condition") {
                let ms = node.duration * (
                    node.unit === "second" ? 1000 :
                    node.unit === "minute" ? 60000 :
                    3600000
                );

                node.status({ fill: "yellow", shape: "dot", text: "Waiting..." });

                setTimeout(() => {
                    node.status({});
                    send(msg);
                    done();
                }, ms);
            } else if (node.waitType === "action_condition") {
                // 简单转发，实际等待由外部逻辑决定
                msg.wait = {
                    action_condition: {
                        event_type: node.event_type,
                        location: node.location
                    }
                };
                send(msg);
                done();
            } else {
                send(msg);
                done();
            }
        });
    }

    RED.nodes.registerType("Wait", WaitNode);
};